# Source for q/spi-qa2.js: Quality assurance (QA program, phantoms, transducer checks, statistics, infection control, electrical safety).
QA="Quality assurance"
Q=[
# --- QA program ---
(QA,"A quality assurance program for ultrasound equipment should include:","Scheduled testing, preventive maintenance and documented results",["Testing only after complaints","Undocumented checks","Repairs only when equipment fails completely"],"Records let the lab spot gradual decline and meet accreditation requirements.","F"),
(QA,"Preventive maintenance of an ultrasound system is:","Routine inspection and servicing to prevent failures",["Repairs after a breakdown","Cleaning the probe between patients only","Replacing the machine yearly"],"It is often done by biomedical engineering or the manufacturer at set intervals.","F"),
(QA,"Echo lab accreditation (such as through IAC) mainly ensures:","Standards for staff credentials, equipment, protocols, reporting and quality improvement",["The lab is the largest in the region","Patients pay less","Only physicians scan"],"Accreditation often requires regular case review and correlation studies.","F"),
(QA,"Correlating echo findings with cath, surgery or MRI results is used to:","Measure the lab's accuracy and improve performance",["Replace echo","Bill more","Reduce frame rate"],"This is a core part of quality improvement.","F"),
(QA,"Peer review in an echo lab involves:","Colleagues reviewing studies and reports to check consistency and quality",["Patients reviewing images","Only the manufacturer reviewing images","Deleting old studies"],"It helps reduce variability between sonographers and readers.","F"),
(QA,"Why should every sonographer in a lab use the same measurement protocol?","To reduce variability so serial studies can be compared",["To slow down exams","To use more storage","It doesn't matter"],"Standardized protocols improve reproducibility.","F"),
# --- Phantoms ---
(QA,"Tissue-mimicking phantoms are commonly made of:","Gel or urethane with tiny scatterers such as graphite",["Pure water","Air","Steel"],"They mimic soft-tissue speed of sound and attenuation.","F"),
(QA,"A tissue-mimicking phantom usually has an attenuation of about:","0.5 to 0.7 dB/cm/MHz",["0 dB/cm/MHz","10 dB/cm/MHz","50 dB/cm/MHz"],"Similar attenuation to tissue makes penetration testing realistic.","C"),
(QA,"Anechoic cylinders of different sizes in a phantom are used to test:","Contrast and the ability to detect small cystic structures at different depths",["Doppler accuracy","Dead zone only","Electrical leakage"],"Small cysts should appear echo-free with sharp borders.","F"),
(QA,"Doppler flow phantoms use a blood-mimicking fluid that contains:","Small scattering particles in a fluid of blood-like viscosity",["Pure water","Air bubbles only","Real blood"],"A pump drives the fluid through tubes at known velocities.","C"),
(QA,"A string phantom differs from a flow phantom because it:","Uses a moving string at a known speed instead of fluid in a tube",["Has no motion","Tests grayscale","Measures temperature"],"It is simple and precise for checking velocity accuracy.","F"),
(QA,"Maximum depth of visualization (penetration) measured on a phantom decreasing over time suggests:","Declining transducer or system sensitivity",["Improved performance","Normal aging of the phantom only","Aliasing"],"Compare with baseline results using the same settings.","F"),
(QA,"Phantom tests should be performed with:","The same, recorded settings each time",["Random settings","Maximum gain always","Different transducers each time"],"Consistent settings make results comparable over time.","F"),
(QA,"Caliper accuracy is checked on a phantom by:","Measuring known distances between targets and comparing them",["Measuring the patient","Using color Doppler","Measuring heart rate"],"Errors usually point to calibration problems in the system.","F"),
(QA,"The tissue-mimicking material in a phantom can change over time by:","Drying out, which changes its speed and attenuation",["Becoming radioactive","Increasing in size","Changing color only"],"Store phantoms as instructed and check their expiry.","C"),
# --- Transducer and system checks ---
(QA,"A vertical dark line running through every image from one transducer suggests:","A failed element or channel",["Normal speckle","Reverberation","Aliasing"],"Report it and remove the transducer from service.","F"),
(QA,"Delamination of a transducer face appears as:","Bubbling or separation of the lens, causing poor images",["A clean, smooth face","Brighter images","Better penetration"],"It can result from wrong cleaning agents or physical damage.","F"),
(QA,"Daily visual inspection of transducers checks for:","Cracks, cuts, delamination and cable damage",["Only the brand name","Phantom calibration","Software updates"],"Damaged probes can injure patients and transmit infection.","F"),
(QA,"Leakage current testing is most important for:","Transducers that enter the body, such as TEE probes",["Keyboards","Monitors","Printers"],"Current close to the heart is more dangerous (microshock risk).","F"),
(QA,"Microshock is especially dangerous because:","Even very small currents delivered close to the heart can cause ventricular fibrillation",["It only affects the skin","It requires very high voltages","It only damages equipment"],"Patients with catheters, pacing wires or TEE probes are at higher risk.","C"),
(QA,"Monitors should be checked with a test pattern (such as SMPTE) to ensure:","Correct brightness, contrast and gray-scale display",["Doppler accuracy","Transducer sensitivity","Correct patient ID"],"A badly set monitor misleads gain adjustments.","C"),
(QA,"Using an extension cord with an ultrasound machine is:","Not recommended; plug directly into a grounded hospital-grade outlet",["Required","Always safe","Better for image quality"],"Extension cords can break the ground and create hazards.","F"),
(QA,"If a patient reports a tingling sensation from the transducer, the sonographer should:","Stop, remove the probe from use and report it for electrical safety testing",["Continue scanning","Increase output","Add more gel"],"It may indicate leakage current.","F"),
# --- Statistics ---
(QA,"The false negative rate equals:","1 − sensitivity",["1 − specificity","PPV − NPV","Accuracy − PPV"],"If sensitivity is 90%, 10% of diseased patients are missed.","F"),
(QA,"The false positive rate equals:","1 − specificity",["1 − sensitivity","PPV ÷ NPV","Prevalence"],"If specificity is 85%, 15% of normal patients are wrongly called abnormal.","F"),
(QA,"Prevalence of disease in a study population is:","The proportion of people who have the disease at a given time",["The rate of new cases","The test's sensitivity","The test's accuracy"],"Incidence is the rate of new cases over time.","F"),
(QA,"TP 60, FN 20, FP 10, TN 110. What is the sensitivity?","75%",["86%","92%","85%"],"Sensitivity = 60 ÷ (60 + 20) = 75%.","C"),
(QA,"TP 60, FN 20, FP 10, TN 110. What is the specificity?","92%",["75%","86%","85%"],"Specificity = 110 ÷ (110 + 10) ≈ 92%.","C"),
(QA,"TP 60, FN 20, FP 10, TN 110. What is the positive predictive value?","86%",["75%","92%","85%"],"PPV = 60 ÷ (60 + 10) ≈ 86%.","C"),
(QA,"TP 60, FN 20, FP 10, TN 110. What is the negative predictive value?","85%",["92%","75%","86%"],"NPV = 110 ÷ (110 + 20) ≈ 85%.","C"),
(QA,"TP 60, FN 20, FP 10, TN 110. What is the accuracy?","85%",["75%","92%","60%"],"Accuracy = (60 + 110) ÷ 200 = 85%.","C"),
(QA,"A ROC (receiver operating characteristic) curve plots:","Sensitivity against 1 − specificity for different cutoffs",["PPV against NPV","Accuracy against prevalence","Velocity against time"],"The area under the curve shows how well a test separates disease from normal.","C"),
(QA,"An area under the ROC curve of 0.5 means:","The test is no better than chance",["The test is perfect","The test is excellent","The test always gives false positives"],"An area of 1.0 is a perfect test.","C"),
(QA,"A correlation coefficient (r) of +0.95 between echo and MRI EF means:","A strong positive relationship between the two measurements",["No relationship","A strong negative relationship","The two methods always give identical values"],"Strong correlation doesn't prove agreement; a Bland-Altman analysis checks agreement.","C"),
(QA,"A Bland-Altman plot is used to assess:","Agreement between two measurement methods, showing bias and limits of agreement",["Sensitivity","Prevalence","Doppler shift"],"It plots the difference between methods against their average.","C"),
(QA,"In a normal distribution, about what percentage of values fall within 2 standard deviations of the mean?","95%",["50%","68%","99.9%"],"About 68% fall within 1 SD. Reference ranges are often mean ± 2 SD.","F"),
(QA,"The median of a set of measurements is:","The middle value when the values are ranked",["The average","The most common value","The difference between highest and lowest"],"The mode is the most frequent value; the mean is the average.","F"),
(QA,"Coefficient of variation is used to express:","Variability relative to the mean, often for measurement reproducibility",["Sensitivity","Prevalence","Accuracy"],"CV = standard deviation ÷ mean × 100%.","C"),
(QA,"A systematic error (bias) in a measurement is one that:","Consistently pushes results in the same direction",["Varies randomly","Cancels out with repeated measurements","Only happens once"],"Calibration errors are typical systematic errors.","C"),
(QA,"Random error in measurements is reduced by:","Averaging repeated measurements",["Using a biased method","Measuring once","Ignoring outliers always"],"This is why Doppler velocities are averaged over several beats.","F"),
# --- Infection control and occupational safety ---
(QA,"The chain of infection includes a pathogen, reservoir, portal of exit, mode of transmission, portal of entry and:","A susceptible host",["A transducer","A phantom","A gel warmer"],"Breaking any link, such as by hand hygiene, prevents infection.","F"),
(QA,"A healthcare-associated infection is:","An infection acquired while receiving care in a healthcare setting",["An infection present before admission","A genetic condition","An allergic reaction"],"Contaminated equipment and hands are common sources.","F"),
(QA,"Sterilization differs from high-level disinfection because sterilization:","Destroys all microorganisms including bacterial spores",["Kills only some bacteria","Uses only soap","Is used for noncritical items"],"High-level disinfection kills all microorganisms except large numbers of spores.","F"),
(QA,"After a needlestick injury, the first step is to:","Wash the area with soap and water and report it immediately",["Ignore it if there is no bleeding","Apply bleach to the wound","Wait until the end of the shift"],"Prompt reporting allows testing and preventive treatment.","F"),
(QA,"Healthcare workers exposed to blood should be vaccinated against:","Hepatitis B",["Influenza only","Measles only","Rabies"],"Employers must offer hepatitis B vaccination under OSHA bloodborne pathogen rules.","F"),
(QA,"The agency that sets workplace bloodborne pathogen standards in the US is:","OSHA",["FDA","AIUM","ARDMS"],"The FDA regulates devices and acoustic output.","F"),
(QA,"Ultrasound gel warmers can be a source of infection because:","Warm, moist conditions can support bacterial growth in gel",["Heat sterilizes gel","They raise patient exposure","They damage the transducer"],"Use single-use gel for high-risk patients and procedures.","C"),
(QA,"Gloves should be changed:","Between patients and when moving from a dirty to a clean task",["Once per shift","Only when torn","Never during an exam"],"Perform hand hygiene after removing gloves.","F"),
(QA,"If disinfectant splashes into the eyes, the sonographer should:","Rinse at an eyewash station for about 15 minutes and report it",["Rub the eyes","Ignore it","Apply gel"],"Safety data sheets describe first aid for each chemical.","F"),
(QA,"Safety data sheets (SDS) give information about:","Chemical hazards, handling and first aid for products such as disinfectants",["Transducer frequency","Patient history","Doppler settings"],"They must be accessible to staff who use the chemicals.","F"),
# --- Regulation ---
(QA,"In the United States, acoustic output of diagnostic ultrasound devices is regulated by the:","FDA",["OSHA","AIUM","ARDMS"],"The AIUM publishes safety statements and guidelines but does not regulate devices.","F"),
(QA,"The output display standard requires machines to show:","Mechanical and thermal indices so the user can manage exposure",["Patient weight","Doppler shift","Frame rate only"],"It puts responsibility on the user to follow ALARA.","F"),
(QA,"A lab's record of equipment malfunctions and repairs is important because it:","Documents problems, shows trends and supports patient safety",["Is not needed","Replaces preventive maintenance","Is only for billing"],"Serious device-related injuries must also be reported under hospital policy.","F"),
]
